package com.doro.music.ui.screen.settings

import android.content.Intent
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.verticalScroll
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.rounded.ChevronRight
import androidx.compose.material3.ExperimentalMaterial3Api
import androidx.compose.material3.Icon
import androidx.compose.material3.ListItem
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.res.stringResource
import androidx.navigation3.runtime.EntryProviderScope
import androidx.navigation3.runtime.NavKey
import androidx.core.net.toUri
import com.doro.music.R
import com.doro.music.ext.getAppVersionName
import com.doro.music.ui.component.SettingsScaffold

fun EntryProviderScope<NavKey>.aboutSettingsEntry(onBack: () -> Unit) {
    entry<SettingsNavKey.About> {
        AboutSettingsScreen(onBack = onBack)
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AboutSettingsScreen(onBack: () -> Unit) {
    val context = LocalContext.current

    // 使用扩展函数获取版本号
    val versionName = remember {
        context.getAppVersionName()
    }

    // 从资源文件获取GitHub URL
    val githubUrl = stringResource(R.string.github_url)

    SettingsScaffold(
        title = stringResource(R.string.about_app),
        onBack = onBack
    ) { paddingValues ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues)
                .verticalScroll(rememberScrollState())
        ) {
            ListItem(
                headlineContent = { Text(stringResource(R.string.version)) },
                supportingContent = { Text(versionName) }
            )
            ListItem(
                modifier = Modifier.clickable {
                    context.startActivity(Intent(Intent.ACTION_VIEW, GITHUB_URL.toUri()))
                },
                headlineContent = { Text(stringResource(R.string.open_source_licenses)) },
                trailingContent = {
                    Icon(
                        imageVector = Icons.Rounded.ChevronRight,
                        contentDescription = null
                    )
                }
            )
        }
    }
}

package com.doro.music.ui.screen.settings

import android.content.Intent
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.verticalScroll
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.rounded.ChevronRight
import androidx.compose.material3.ExperimentalMaterial3Api
import androidx.compose.material3.Icon
import androidx.compose.material3.ListItem
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.res.stringResource
import androidx.navigation3.runtime.EntryProviderScope
import androidx.navigation3.runtime.NavKey
import androidx.core.net.toUri
import com.doro.music.R
import com.doro.music.ext.getAppVersionName
import com.doro.music.ui.component.SettingsScaffold

fun EntryProviderScope<NavKey>.aboutSettingsEntry(onBack: () -> Unit) {
    entry<SettingsNavKey.About> {
        AboutSettingsScreen(onBack = onBack)
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AboutSettingsScreen(onBack: () -> Unit) {
    val context = LocalContext.current

    // 使用扩展函数获取版本号
    val versionName = remember {
        context.getAppVersionName()
    }

    // 从资源文件获取GitHub URL
    val githubUrl = stringResource(R.string.github_url)

    SettingsScaffold(
        title = stringResource(R.string.about_app),
        onBack = onBack
    ) { paddingValues ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues)
                .verticalScroll(rememberScrollState())
        ) {
            ListItem(
                headlineContent = { Text(stringResource(R.string.version)) },
                supportingContent = { Text(versionName) }
            )

            ListItem(
                modifier = Modifier.clickable {
                    try {
                        val intent = Intent(Intent.ACTION_VIEW, githubUrl.toUri())
                        context.startActivity(intent)
                    } catch (_: Exception) {
                        // 处理无法启动浏览器的情况（例如没有浏览器应用）
                    }
                },
                headlineContent = { Text(stringResource(R.string.open_source_licenses)) },
                trailingContent = {
                    Icon(
                        imageVector = Icons.Rounded.ChevronRight,
                        contentDescription = stringResource(R.string.open_source_licenses)
                    )
                }
            )
        }
    }
}
